function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Sky
  brush.fill("#2954ff", 70);       // Cyan blue
  brush.fill("#87cefa", 180);       // Light blue
  brush.fill("#2954ff", 150);       // Blue with some pink
  brush.fill("#21c2e3", 150);       // Azul ocean
  brush.fill("#74c8ff", 180);       // Far blue
  brush.fill("#007897", 180);       // Navy blue
  brush.fill("#815300", 255);       // Violet pink

  // Ground
  brush.fill("#000f6e", 90);       // Emerald green
  brush.fill("#004d15", 180);       // Green with brown

  // Hills
  brush.fill("#007897", 180);       // Green with purple
  brush.beginShape(MITER)
    brush.vertex(400, 400);
    brush.vertex(0, 100)
    brush.vertex(280, 570)
    brush.vertex(420, 650)
    brush.endShape(true);
  brush.fill("#2954ff", 180);       // Green with purple
  brush.endShape()

  // Sit
  brush.fill("#000f6e", 90);       // Yellow

  // Detail brush
  brush.fill("#003300", 255);       // Green

  // Append to composition
  brush.endComposition();
}
