function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();

  // Create a sky with blue color.
  brush.fill("#5898b3", 80); // "5898b3" is a skyblue color hex string
  brush.circle(200, 200, 400); // draw big round circle

  // Create a few green hills on top of the blue sky.
  brush.fill("#2a5648", 200); // "2a5648" is a green hex string
  brush.circle(200, 200, 200); // draw green hill first (since it is farther away, it is first in the blur)
  brush.fill("#315536", 200); // "315536" is a green hex string
  brush.circle(200, 200, 180); // draw green hill closer to us (since it is closer, it is behind the hill
  brush.fill("#37572f", 200); // "37572f" is a green hex string
  brush.circle(200, 200, 160); // draw green hill even closer to us (since it is closer, it is behind the hill

  // Create the ground covering the hills
  brush.fill("#1a2f2f", 10); // "1a2f2f" is a dark green hex string
  brush.circle(200, 200, 600); // draw a green area beneath the hills
}
