function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke(); // Stop drawing thin lines

  // First, paint the sky
  brush.fill("blue", 150); // Fill the brush with the sky color, with a 10% opacity.
  brush.circle(0, 0, 300); // Draw a circle representing the sunset on top of the green hills. The sun is at a brighter, white color for the center of the circle.
  brush.fill("white", 100); // Fill a slightly smaller circle with white, for the sun.
  brush.circle(0, 0, 35); // Paint a tiny white circle in the center of the larger circle for the sun.

  // Now paint the green hills
  brush.fill("#769166", 30); // Fill with green for the hills.
  brush.circle(0, 0, 180); // Draw a larger hill on the side of the green hills. This hill is slightly narrower than the previous one.
  brush.fill("#425b3b", 30); // Fill with darker green for the hills.
  brush.circle(0, 0, 140); // Draw a larger hill on the side of the green hills. This hill is slightly narrower than the previous one.

  // Lastly, paint the ground
  brush.fill("#e1c4a0", 100); // Fill the ground with a greenish yellow color for the grass.
  brush.circle(0, 0, 25); // Draw a circle representing a hill on the side of the green hills, just a little bit taller than the previous hills.

  brush.endShape(true); // End the shapes
}
